import { readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vitest';
import { parse as parseYaml } from 'yaml';
import {
  attemptId,
  ceilingNanos,
  costNanos,
  nanosToUsd,
  usdToNanos,
  validateConfig,
  validateLedger,
  validateLedgerRow,
  validateRunState,
  type LedgerRow,
  type RunState,
  type TallyConfig,
} from './index.js';

const fixture = (name: string) => readFileSync(fileURLToPath(new URL(`./fixtures/${name}`, import.meta.url)), 'utf8');

const ledger = JSON.parse(fixture('finished-run/ledger.json')) as LedgerRow[];
const run = JSON.parse(fixture('finished-run/run.json')) as RunState;
const config = parseYaml(fixture('finished-run/tally.yaml')) as TallyConfig;

// A row written against the TypeScript type. `npm run typecheck` fails if the
// type drifts from this shape; the test below fails if the JSON Schema does.
const typedRow: LedgerRow = {
  schemaVersion: 1,
  attemptId: 'run-1:T1:1',
  runId: 'run-1',
  taskId: 'T1',
  taskTitle: 'Fix off-by-one in pager',
  attempt: 1,
  size: 'small',
  tier: 'cheap',
  model: 'some-model',
  harness: 'some-harness',
  sessionId: null,
  branch: null,
  tokens: { uncachedInput: 1000, cachedInput: 0, output: 100, total: 1100 },
  estimatedCostNanos: 1_500_000,
  costSource: 'list-price',
  ceilingNanos: 300_000_000,
  result: 'passed',
  resultReason: null,
  escalatedFrom: null,
  handoff: 'none',
  prUrl: null,
  traceUrl: null,
  checkpointId: null,
  checkpointUrl: null,
  decision: 'Small task with existing tests, so the cheap tier is expected to finish it.',
  startedAt: '2026-10-11T08:00:00Z',
  endedAt: '2026-10-11T08:04:00Z',
};

describe('money helpers', () => {
  it('converts between USD and integer nanos', () => {
    expect(usdToNanos(1)).toBe(1_000_000_000);
    expect(usdToNanos(0.3)).toBe(300_000_000);
    expect(nanosToUsd(2_345_760)).toBeCloseTo(0.00234576, 10);
  });

  it('prices tokens at list price', () => {
    const price = { inputUsdPerMTok: 0.2, cachedInputUsdPerMTok: 0.02, outputUsdPerMTok: 1.2 };
    // Figures observed from the AO usage endpoint for a real Codex session.
    expect(costNanos({ uncachedInput: 10_592, cachedInput: 11_008, output: 6, total: 21_606 }, price)).toBe(2_345_760);
  });

  it('derives a ceiling from task size and tier fraction', () => {
    const cheap = config.tiers[0]!;
    expect(ceilingNanos(config, 'medium', cheap)).toBe(usdToNanos(config.ceilings.bySizeUsd.medium * cheap.ceilingFraction));
  });

  it('builds a stable attempt id', () => {
    expect(attemptId('run-1', 'T5', 2)).toBe('run-1:T5:2');
  });
});

describe('ledger row schema', () => {
  it('accepts a row that satisfies the TypeScript type', () => {
    expect(validateLedgerRow(typedRow)).toEqual({ ok: true, errors: [] });
  });

  it('rejects a missing decision sentence', () => {
    const { decision: _drop, ...rest } = typedRow;
    const res = validateLedgerRow(rest);
    expect(res.ok).toBe(false);
    expect(res.errors.join(' ')).toContain('decision');
  });

  it('rejects unknown fields, results and sizes', () => {
    expect(validateLedgerRow({ ...typedRow, extra: 1 }).ok).toBe(false);
    expect(validateLedgerRow({ ...typedRow, result: 'maybe' }).ok).toBe(false);
    expect(validateLedgerRow({ ...typedRow, size: 'huge' }).ok).toBe(false);
  });

  it('rejects fractional or negative money and tokens', () => {
    expect(validateLedgerRow({ ...typedRow, estimatedCostNanos: 1.5 }).ok).toBe(false);
    expect(validateLedgerRow({ ...typedRow, ceilingNanos: -1 }).ok).toBe(false);
    expect(validateLedgerRow({ ...typedRow, tokens: { ...typedRow.tokens, output: -3 } }).ok).toBe(false);
  });
});

describe('finished-run fixture', () => {
  it('validates against all three schemas', () => {
    expect(validateConfig(config)).toEqual({ ok: true, errors: [] });
    expect(validateLedger(ledger)).toEqual({ ok: true, errors: [] });
    expect(validateRunState(run)).toEqual({ ok: true, errors: [] });
  });

  it('has exactly one escalated task, whose second attempt points at the first', () => {
    const escalated = run.tasks.filter((t) => t.escalated);
    expect(escalated).toHaveLength(1);
    const rows = ledger.filter((r) => r.taskId === escalated[0]!.taskId);
    expect(rows.map((r) => r.attempt)).toEqual([1, 2]);
    expect(rows[0]!.result).not.toBe('passed');
    expect(rows[1]!.result).toBe('passed');
    expect(rows[1]!.escalatedFrom).toBe(rows[0]!.attemptId);
    expect(ledger.filter((r) => r.escalatedFrom !== null)).toHaveLength(1);
  });

  it('prices every row from the config tiers, never from hard-coded numbers', () => {
    for (const row of ledger) {
      const tier = config.tiers.find((t) => t.name === row.tier);
      expect(tier, `tier ${row.tier}`).toBeDefined();
      expect(row.model).toBe(tier!.model);
      expect(row.harness).toBe(tier!.harness);
      expect(row.tokens.total).toBe(row.tokens.uncachedInput + row.tokens.cachedInput + row.tokens.output);
      expect(row.estimatedCostNanos).toBe(costNanos(row.tokens, tier!.price));
      expect(row.ceilingNanos).toBe(ceilingNanos(config, row.size, tier!));
      expect(row.attemptId).toBe(attemptId(row.runId, row.taskId, row.attempt));
    }
  });

  it('keeps run state consistent with the ledger', () => {
    const total = ledger.reduce((sum, r) => sum + r.estimatedCostNanos, 0);
    expect(run.budget.spentNanos).toBe(total);
    expect(run.budget.limitNanos).toBe(usdToNanos(config.budget.usd));
    expect(run.budget.spentNanos).toBeLessThanOrEqual(run.budget.limitNanos);
    expect(run.status).toBe('finished');
    for (const task of run.tasks) {
      const rows = ledger.filter((r) => r.taskId === task.taskId);
      expect(task.attempts).toBe(rows.length);
      expect(task.spentNanos).toBe(rows.reduce((sum, r) => sum + r.estimatedCostNanos, 0));
      expect(rows.every((r) => r.runId === run.runId)).toBe(true);
    }
    expect(new Set(ledger.map((r) => r.taskId))).toEqual(new Set(run.tasks.map((t) => t.taskId)));
  });

  it('only stops attempts that actually crossed their ceiling', () => {
    for (const row of ledger) {
      if (row.result === 'stopped') expect(row.estimatedCostNanos).toBeGreaterThanOrEqual(row.ceilingNanos);
      if (row.result === 'passed') expect(row.estimatedCostNanos).toBeLessThanOrEqual(row.ceilingNanos);
    }
  });
});

describe('config schema', () => {
  it('requires repo, test command and at least one tier', () => {
    expect(validateConfig({ ...config, repo: undefined }).ok).toBe(false);
    expect(validateConfig({ ...config, test: {} }).ok).toBe(false);
    expect(validateConfig({ ...config, tiers: [] }).ok).toBe(false);
  });

  it('accepts any harness and model strings for a tier', () => {
    const tiers = [{ ...config.tiers[0]!, harness: 'codex', model: 'gpt-5.6-luna' }, ...config.tiers.slice(1)];
    expect(validateConfig({ ...config, tiers }).ok).toBe(true);
  });

  it('rejects a ceiling fraction above 1 and an unknown budget source', () => {
    const tiers = [{ ...config.tiers[0]!, ceilingFraction: 1.5 }];
    expect(validateConfig({ ...config, tiers }).ok).toBe(false);
    expect(validateConfig({ ...config, budget: { source: 'guess', usd: 5 } }).ok).toBe(false);
  });
});

/**
 * The shared contract between the engine, the CFO agent and the dashboard.
 *
 * Every type here has a matching JSON Schema in this folder
 * (`*.schema.json`). Change both together and bump SCHEMA_VERSION when a
 * change is not backwards compatible.
 *
 * Money is stored as integer nanos of USD (1 USD = 1_000_000_000), the unit
 * the Agent Orchestrator usage endpoint reports. Config files use plain USD.
 */

export const SCHEMA_VERSION = 1;

export type TaskSize = 'small' | 'medium' | 'large';

/** Outcome of one attempt. `stopped` means the watcher killed it at its ceiling. */
export type AttemptResult = 'passed' | 'failed' | 'stopped' | 'error';

/** How the cost on a row was obtained. */
export type CostSource =
  /** tokens x list price from tally.yaml (the default, comparable across harnesses) */
  | 'list-price'
  /** the Agent Orchestrator's own estimate, used only when no list price is configured */
  | 'ao-estimate'
  /** a dry-run or demo attempt that spent nothing */
  | 'simulated';

/** How an escalated attempt received the earlier attempt's work. */
export type Handoff = 'none' | 'restart' | 'entire-handoff';

export interface TokenUsage {
  /** Input tokens billed at the full input price. Includes cache writes. */
  uncachedInput: number;
  /** Input tokens read from cache. */
  cachedInput: number;
  output: number;
  /** uncachedInput + cachedInput + output */
  total: number;
}

/** One row per attempt. A task that escalates has two rows. */
export interface LedgerRow {
  schemaVersion: 1;
  /** `${runId}:${taskId}:${attempt}` */
  attemptId: string;
  runId: string;
  taskId: string;
  taskTitle: string;
  /** 1 for the first attempt, 2 for the escalation. */
  attempt: number;
  size: TaskSize;
  /** Name of the tier in tally.yaml that ran this attempt. */
  tier: string;
  model: string;
  harness: string;
  /** Agent Orchestrator session id; null for simulated attempts. */
  sessionId: string | null;
  branch: string | null;
  tokens: TokenUsage;
  estimatedCostNanos: number;
  costSource: CostSource;
  /** Spend ceiling that applied to this attempt. */
  ceilingNanos: number;
  result: AttemptResult;
  /** Short explanation of the result, e.g. "2 tests failing" or "ceiling crossed". */
  resultReason: string | null;
  /** attemptId of the attempt this one took over from, if it is an escalation. */
  escalatedFrom: string | null;
  handoff: Handoff;
  prUrl: string | null;
  traceUrl: string | null;
  checkpointId: string | null;
  checkpointUrl: string | null;
  /** The CFO agent's one-sentence reason for choosing this tier. */
  decision: string;
  startedAt: string;
  endedAt: string | null;
}

export type Ledger = LedgerRow[];

export type RunMode = 'tally' | 'baseline';
export type RunStatus = 'running' | 'finished' | 'interrupted';
export type TaskStatus = 'pending' | 'running' | 'passed' | 'failed' | 'skipped';
export type BudgetSource = 'config' | 'cfoai';

export type IntegrationName = 'neatlogs' | 'entire' | 'cfoai' | 'github' | 'slack';
/** `off` = switched off in config, `missing` = on but not usable, `error` = failed during the run. */
export type IntegrationStatus = 'ok' | 'off' | 'missing' | 'error';

export interface IntegrationState {
  status: IntegrationStatus;
  /** What Tally does instead, or what went wrong. */
  detail: string | null;
}

export interface TaskState {
  taskId: string;
  title: string;
  issueNumber: number | null;
  issueUrl: string | null;
  /** null until the sizer has run. */
  size: TaskSize | null;
  status: TaskStatus;
  /** Why a task is failed or skipped, e.g. "not started: no budget". */
  statusReason: string | null;
  attempts: number;
  /** Tier of the latest attempt. */
  tier: string | null;
  model: string | null;
  spentNanos: number;
  escalated: boolean;
  prUrl: string | null;
}

export interface RunState {
  schemaVersion: 1;
  runId: string;
  mode: RunMode;
  /** True when workers were simulated and nothing was spent. */
  dryRun: boolean;
  status: RunStatus;
  /** The repository the run worked on, as written in tally.yaml. */
  repo: string;
  /** Commit every task branched from. */
  baseCommit: string | null;
  startedAt: string;
  updatedAt: string;
  endedAt: string | null;
  budget: {
    source: BudgetSource;
    limitNanos: number;
    /** Always the sum of estimatedCostNanos over this run's ledger rows. */
    spentNanos: number;
  };
  tasks: TaskState[];
  integrations: Record<IntegrationName, IntegrationState>;
}

export interface TierPrice {
  inputUsdPerMTok: number;
  cachedInputUsdPerMTok: number;
  outputUsdPerMTok: number;
}

export interface Tier {
  /** Free-form label, e.g. cheap / middle / top. Referenced by ledger rows. */
  name: string;
  /** Any harness the Agent Orchestrator supports. */
  harness: string;
  model: string;
  /** Published list price. Cost is always tokens x this. */
  price: TierPrice;
  /** Share of the size ceiling this tier may spend, in (0, 1]. */
  ceilingFraction: number;
}

export interface TallyConfig {
  version: 1;
  repo: {
    /** Local checkout, relative to tally.yaml. */
    path: string;
    /** owner/name on GitHub, when issues or PRs are used. */
    slug?: string;
    baseBranch: string;
    /** Agent Orchestrator project id, when it differs from the default for the checkout. */
    aoProject?: string;
  };
  test: {
    /** Run in the task's checkout; exit code 0 means the task passed. */
    command: string;
    /** Run once per fresh checkout before the test command. */
    setupCommand?: string;
    timeoutSec?: number;
  };
  backlog: {
    source: 'github-issues' | 'file';
    issueLabel?: string;
    /** YAML backlog file, relative to tally.yaml. */
    file?: string;
  };
  /** Ordered from cheapest to strongest. Escalation moves one step right. */
  tiers: Tier[];
  ceilings: {
    /** What the strongest tier may spend on a task of each size, in USD. */
    bySizeUsd: Record<TaskSize, number>;
  };
  budget: {
    source: BudgetSource;
    /** The budget, or the fallback when the cfo.ai scenario cannot be read. */
    usd: number;
    cfoai?: { scenario: string };
  };
  concurrency?: number;
  integrations: Record<'neatlogs' | 'entire' | 'cfoai' | 'slack', boolean>;
}

import type { TallyConfig, TaskSize, Tier, TierPrice, TokenUsage } from './types.js';

export const NANOS_PER_USD = 1_000_000_000;

export function usdToNanos(usd: number): number {
  return Math.round(usd * NANOS_PER_USD);
}

export function nanosToUsd(nanos: number): number {
  return nanos / NANOS_PER_USD;
}

/** Tokens x list price, in nanos. A price per million tokens is 1000 nanos per token per USD. */
export function costNanos(tokens: TokenUsage, price: TierPrice): number {
  return Math.round(
    tokens.uncachedInput * price.inputUsdPerMTok * 1000 +
      tokens.cachedInput * price.cachedInputUsdPerMTok * 1000 +
      tokens.output * price.outputUsdPerMTok * 1000,
  );
}

/** The spend ceiling for one attempt: the size ceiling scaled by the tier's fraction. */
export function ceilingNanos(config: TallyConfig, size: TaskSize, tier: Tier): number {
  return usdToNanos(config.ceilings.bySizeUsd[size] * tier.ceilingFraction);
}

export function attemptId(runId: string, taskId: string, attempt: number): string {
  return `${runId}:${taskId}:${attempt}`;
}

